"""One saved modifier interface for every prepared aggregate network.

Clean editable polylines enter through Geometry. Private relation tables use
object inputs; they are never loose vertices of the editable source mesh.
Physical construction always runs at exaggeration one. Display exaggeration
is applied afterwards and therefore cannot alter construction decisions.
"""
import hashlib
import bpy
from .path_surface_nodes import _Nodes
from . import boundary_quad_bridge_nodes as bridge


def display_surface(g, geometry, inp, *, collection_sources=False):
    """Apply the existing display law after physical construction."""
    for key, selection in (('Pavement', True), ('Grass', g.compare(g.named('_cn_face_kind'), 4, kind='INT'))):
        material = g.node('GeometryNodeSetMaterial', key+' display material')
        g.set(geometry, material.inputs['Geometry']); g.set(selection, material.inputs['Selection'])
        g.set(inp.outputs[key], material.inputs['Material']); geometry = material.outputs['Geometry']
    pos = g.node('GeometryNodeInputPosition', 'Physical position').outputs[0]
    offset = g.xyz(z=g.math('MULTIPLY', g.component(pos, 'Z'), g.math('SUBTRACT', inp.outputs['Height Exaggeration'], 1.)))
    display = g.node('GeometryNodeSetPosition', 'Display exaggeration only')
    g.set(geometry, display.inputs['Geometry']); g.set(offset, display.inputs['Offset'])
    shown = display.outputs['Geometry']
    if collection_sources:
        units = g.node('GeometryNodeTransform', 'Physical metres to Blender units')
        g.set(shown, units.inputs['Geometry']); g.set(inp.outputs['Metres to Blender Units'], units.inputs['Scale'])
        shown = units.outputs['Geometry']
    return shown


def build(solver, *, collection_sources=False, provider_output=False):
    name = 'Prochitecture Streets / Aggregate editable network v1 / '+hashlib.sha256(solver.name.encode()).hexdigest()[:16]
    if collection_sources: name += ' / Canonical collection inputs v1'
    if provider_output:
        if not collection_sources: raise ValueError('Native aggregate providers require separate source objects')
        name += ' / Physical provider packet v1'
    if name in bpy.data.node_groups: return bpy.data.node_groups[name]
    tree = bpy.data.node_groups.new(name, 'GeometryNodeTree'); tree.is_modifier = True
    g = _Nodes(tree)
    def socket(key, kind, default=None, direction='INPUT'):
        item = tree.interface.new_socket(name=key, in_out=direction, socket_type=kind)
        if default is not None: item.default_value = default
        return item
    socket('Geometry', 'NodeSocketGeometry')
    if collection_sources:
        socket('Source Objects', 'NodeSocketCollection')
        socket('Source Vertex Count', 'NodeSocketInt', 0)
        socket('Source Edge Count', 'NodeSocketInt', 0)
        socket('Metres to Blender Units', 'NodeSocketFloat', 1.)
    tables = [s.name for s in solver.interface.items_tree if s.item_type == 'SOCKET'
              and s.in_out == 'INPUT' and s.socket_type == 'NodeSocketGeometry' and s.name != 'Sources']
    for key in tables: socket(key, 'NodeSocketObject')
    socket('Cell Size', 'NodeSocketFloat', .7).min_value = .01
    resolution = socket('Mesh Resolution', 'NodeSocketInt', 1)
    resolution.min_value = 1; resolution.max_value = 4
    resolution.description = '1 uses the authored cell size; each higher level halves the target size'
    socket('Height Exaggeration', 'NodeSocketFloat', 10.).min_value = 0.
    socket('Separator Count', 'NodeSocketInt', 0).min_value = 0
    if provider_output: socket('Aggregate Provider Key', 'NodeSocketInt', 0)
    for key in ('Pavement', 'Grass'): socket(key, 'NodeSocketMaterial')
    for key in ('Geometry', 'Evidence'): socket(key, 'NodeSocketGeometry', direction='OUTPUT')
    socket('Valid', 'NodeSocketBool', direction='OUTPUT')
    inp = g.node('NodeGroupInput', 'Editable polylines and prepared relations')
    out = g.node('NodeGroupOutput', 'Display surface and physical evidence')
    call = g.node('GeometryNodeGroup', 'Shared physical aggregate construction'); call.node_tree = solver
    source = inp.outputs['Geometry']; source_valid = True
    if collection_sources:
        from .live_input_nodes import source_geometry
        source, source_valid = source_geometry(tree, inp)
        source_valid = g.all(source_valid, g.compare(inp.outputs['Metres to Blender Units'], 0., 'GREATER_THAN'))
    g.set(source, call.inputs['Sources'])
    for key in tables:
        info = g.node('GeometryNodeObjectInfo', 'Private '+key)
        info.transform_space = 'ORIGINAL' if collection_sources else 'RELATIVE'
        g.set(inp.outputs[key], info.inputs['Object']); g.set(info.outputs['Geometry'], call.inputs[key])
    level = g.math('SUBTRACT', inp.outputs['Mesh Resolution'], 1.)
    g.set(g.math('DIVIDE', inp.outputs['Cell Size'], g.math('POWER', 2., level)), call.inputs['Cell Size'])
    g.set(1., call.inputs['Height Exaggeration'])
    g.set(inp.outputs['Separator Count'], call.inputs['Separator Count'])
    valid = g.all(source_valid, call.outputs['Valid'], g.compare(inp.outputs['Mesh Resolution'], 1, 'GREATER_EQUAL', 'INT'),
                  g.compare(inp.outputs['Mesh Resolution'], 4, 'LESS_EQUAL', 'INT'),
                  g.compare(inp.outputs['Height Exaggeration'], 0., 'GREATER_EQUAL'))
    geometry = g.switch(valid, None, call.outputs['Geometry'], 'GEOMETRY')
    if not provider_output:
        g.set(display_surface(g, geometry, inp, collection_sources=collection_sources), out.inputs['Geometry'])
    g.set(valid, out.inputs['Valid'])
    parts = []
    for index, key in enumerate(('Geometry', 'Mouths', 'Status', 'Diagnostics', 'End Ports')):
        geo = g.store(call.outputs[key], 'ag_network_kind', index, 'INT')
        parts.append(g.store(geo, 'ag_network_valid', valid, 'BOOLEAN'))
    # Blender prepends multi-input links: preserve the existing evidence order.
    evidence = bridge._join(g, *reversed(parts))
    g.set(evidence, out.inputs['Evidence'])
    if provider_output:
        from .aggregate_provider_nodes import packet
        g.set(packet(g, geometry, evidence, valid, inp.outputs['Aggregate Provider Key']), out.inputs['Geometry'])
        tree['blosm_street_input_schema'] = 'aggregate_provider.1'
        tree['blosm_aggregate_provider'] = 1
    tree['st_aggregate_modifier_version'] = 1
    tree['st_aggregate_collection_inputs'] = int(collection_sources)
    tree['st_aggregate_physical_solver'] = solver.name
    return tree
